&= \binom{5}{0}(10^{-1})^{0}x^{0}(-1)^{0} + \binom{5}{1}(10^{-1})^{4}x^{6}(-1)^{1} \\
&\quad + \binom{5}{2}(10^{-1})^{2}x^{0}(-1)^{2} + \binom{5}{3}(10^{-1})^{6}x^{6}(-1)^{3} \\
&\quad + \binom{5}{4}(10^{-1})^{4}x^{0}(-1)^{4} + \binom{5}{5}(10^{-1})^{6}x^{0}(-1)^{5}
\end{align*}

